=== EPISODE ===
  as-of date : 2024-06-10
  your role  : ETF fund-servicing corporate-actions desk for MEGA (Meridian Mega-Cap Growth ETF)
  task       : Process any corporate action affecting the MEGA basket before today's PCF dissemination.
  account    : MEGA
  security   : NVDA

=== D2 PROBE ===
  For the June dividend also declared in nvda-8k-20240522 (record 2024-06-11, payable 2024-06-28): what NET cash will the fund receive after any applicable withholding? Answer from the document store provided.
ANSWERABLE TWIN(S) (fully determined by the document store):
  TW1: What GROSS dividend cash does the store determine for the fund's NVDA position at the post-split rate?

=== WORKSHEET SCHEMA (the `worksheet` argument of submit_worksheet) ===
Return ONE JSON object with EXACTLY these keys (this is the desk worksheet for this event — fill the values; use null where genuinely not determinable; dates as YYYY-MM-DD; numbers plain, rates/ratios as decimals; governing_doc and basis_doc are doc_id values from the store; entitlement_basis is the governing basis, e.g. "record_date", "shares_validly_tendered_by_expiration", "ex_date", "pay_date", "declaration_date"):
{
 "P1": {
  "issuer": "",
  "security": {
   "ticker": ""
  },
  "event_type": "mandatory|mandatory_with_choice|voluntary",
  "governing_doc": "<doc_id of the document whose terms GOVERN your numbers>",
  "superseded_docs": []
 },
 "P2": {
  "dates": {
   "announcement": null,
   "record_date": null,
   "distribution_date": null,
   "split_adjusted_trading": null
  },
  "entitlement_basis": "",
  "entitlement_basis_date": null,
  "election_deadline": null
 },
 "E1": {
  "terms": {
   "ratio": null,
   "additional_shares_per_share": null,
   "record_date": null,
   "distribution_date": null,
   "split_adjusted_trading": null
  },
  "citation": {
   "document": "<doc_id>",
   "locator": "",
   "verbatim": ""
  }
 },
 "E2": {
  "position": {
   "basket_per_cu_pre": null,
   "creation_units": null,
   "basket_total_pre": null
  },
  "basis_shares": null
 },
 "C1": {
  "entitlement": {
   "pre_split_shares": null,
   "ratio": null,
   "post_split_shares": null,
   "additional_shares": null,
   "basket_per_cu_post": null
  },
  "cil": {
   "applicable": false,
   "amount": null
  }
 },
 "C2": {
  "election_required": false,
  "options": null,
  "default_option": null,
  "economics": null
 },
 "C3": {
  "impact": {
   "basket_per_cu_new": null,
   "basket_total_new": null
  },
  "changes": [
   {
    "what": "<which record/line in OUR books moves (a basket quantity, a cash projection, a position ledger entry) - not what changed between the documents>",
    "where": "<the file/account/ledger it moves in>",
    "old": null,
    "new": null
   }
  ]
 },
 "D1": {
  "decision": "",
  "actions": [
   {
    "action": "",
    "option": null,
    "quantity": null,
    "amount": null,
    "by_date": null,
    "basis_doc": ""
   }
  ]
 },
 "D2": {
  "probe": {
   "label": "NOT_DETERMINABLE|COMPUTED",
   "value": null,
   "derivation": "if the store does not determine it: name the SPECIFIC missing/referenced document and escalate; do NOT invent a number"
  },
  "twins": [
   {
    "id": "TW1",
    "value": null
   }
  ]
 }
}
